// C3dqNegCtl at the start of every key (and 0 again at the flush). The game itself calls several of these functions
// from the first frame, on more than one thread, so a wrong body must not be live outside the A/B.
extern "C" __declspec(dllexport) volatile int C3dqNegCtl[4] = {0, 0x5147454e, 0, 0};   // word 1 = magic; re/frida/js/freeze.js negOn() sets word 0
